// Evaluate campaigns against automation rules
const config = $('Config').first().json;
const campaigns = $input.first().json.data || [];
const actions = [];

campaigns.forEach(campaign => {
  const insights = campaign.insights?.data?.[0] || {};
  const spend = parseFloat(insights.spend || 0);
  const conversions = parseInt(insights.conversions || 0);
  const roas = insights.purchase_roas ? parseFloat(insights.purchase_roas[0].value) : 0;
  const cpa = conversions > 0 ? spend / conversions : 999;
  const dailyBudget = campaign.daily_budget ? campaign.daily_budget / 100 : 0;

  // Skip if not enough spend to evaluate
  if (spend < 20) return;

  // Rule 1: Pause if CPA too high
  if (cpa > config.pauseCpaThreshold) {
    actions.push({
      campaignId: campaign.id,
      campaignName: campaign.name,
      action: 'PAUSE',
      reason: `CPA $${cpa.toFixed(2)} exceeds $${config.pauseCpaThreshold} threshold`,
      currentCpa: cpa
    });
    return;
  }

  // Rule 2: Scale if ROAS is good
  if (roas > config.scaleRoasThreshold) {
    const newBudget = Math.min(
      dailyBudget * (1 + config.budgetIncreasePercent / 100),
      config.maxDailyBudget
    );

    if (newBudget > dailyBudget) {
      actions.push({
        campaignId: campaign.id,
        campaignName: campaign.name,
        action: 'INCREASE_BUDGET',
        reason: `ROAS ${roas.toFixed(2)}x exceeds ${config.scaleRoasThreshold}x threshold`,
        currentBudget: dailyBudget,
        newBudget: newBudget,
        roas: roas
      });
    }
  }
});

return actions.map(a => ({json: a}));
